            del self.store.pending[tx.tx_id]
            event_payload = {
                "tx_id": tx.tx_id,
                "from": tx.sender,
                "to": tx.recipient,
                "amount": tx.amount,
                "signature": signature,
            }
            if tx.nonce is not None:
                event_payload["nonce"] = tx.nonce
